SELECT [SupplierID],[SupplierName],[SupplierCategoryID],[PrimaryContactPersonID],[AlternateContactPersonID],[DeliveryMethodID],[DeliveryCityID],[PostalCityID],[SupplierReference],[BankAccountName],[BankAccountBranch],[BankAccountCode],[BankAccountNumber],[BankInternationalCode],[PaymentDays],[InternalComments],[PhoneNumber],[FaxNumber],[WebsiteURL],[DeliveryAddressLine1],[DeliveryAddressLine2],[DeliveryPostalCode],[PostalAddressLine1],[PostalAddressLine2],[PostalPostalCode],[LastEditedBy],CONVERT(nvarchar(33),[ValidFrom],126) AS [ValidFrom],CONVERT(nvarchar(33),[ValidTo],126) AS [ValidTo] FROM [Purchasing].[Suppliers] ORDER BY [SupplierID]